package matteroverdrive.network;
import matteroverdrive.MatterOverdrive;import matteroverdrive.android.AndroidData;import net.minecraft.core.BlockPos;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.minecraftforge.network.NetworkRegistry;import net.minecraftforge.network.PacketDistributor;import net.minecraftforge.network.simple.SimpleChannel;import java.util.List;
public final class ModNetwork{private static final String PROTOCOL="1";private static int nextId;public static final SimpleChannel CHANNEL=NetworkRegistry.ChannelBuilder.named(new ResourceLocation(MatterOverdrive.MOD_ID,"network")).networkProtocolVersion(()->PROTOCOL).clientAcceptedVersions(PROTOCOL::equals).serverAcceptedVersions(PROTOCOL::equals).simpleChannel();private ModNetwork(){}public static void register(){CHANNEL.registerMessage(nextId++,AndroidStatePacket.class,AndroidStatePacket::encode,AndroidStatePacket::decode,AndroidStatePacket::handle);CHANNEL.registerMessage(nextId++,AndroidAbilityPacket.class,AndroidAbilityPacket::encode,AndroidAbilityPacket::decode,AndroidAbilityPacket::handle);CHANNEL.registerMessage(nextId++,AndroidPerkSelectPacket.class,AndroidPerkSelectPacket::encode,AndroidPerkSelectPacket::decode,AndroidPerkSelectPacket::handle);CHANNEL.registerMessage(nextId++,DataPadOpenPacket.class,DataPadOpenPacket::encode,DataPadOpenPacket::decode,DataPadOpenPacket::handle);CHANNEL.registerMessage(nextId++,DocumentationOpenPacket.class,DocumentationOpenPacket::encode,DocumentationOpenPacket::decode,DocumentationOpenPacket::handle);CHANNEL.registerMessage(nextId++,OmniToolFirePacket.class,OmniToolFirePacket::encode,OmniToolFirePacket::decode,OmniToolFirePacket::handle);CHANNEL.registerMessage(nextId++,StarMapTravelPacket.class,StarMapTravelPacket::encode,StarMapTravelPacket::decode,StarMapTravelPacket::handle);CHANNEL.registerMessage(nextId++,StarMapFleetAttackPacket.class,StarMapFleetAttackPacket::encode,StarMapFleetAttackPacket::decode,StarMapFleetAttackPacket::handle);CHANNEL.registerMessage(nextId++,StarMapEconomyPacket.class,StarMapEconomyPacket::encode,StarMapEconomyPacket::decode,StarMapEconomyPacket::handle);CHANNEL.registerMessage(nextId++,StarMapShipDispatchPacket.class,StarMapShipDispatchPacket::encode,StarMapShipDispatchPacket::decode,StarMapShipDispatchPacket::handle);CHANNEL.registerMessage(nextId++,ContractAbandonPacket.class,ContractAbandonPacket::encode,ContractAbandonPacket::decode,ContractAbandonPacket::handle);}public static void openDataPad(ServerPlayer p,List<String> h){CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new DataPadOpenPacket(h));}public static void openDocumentation(ServerPlayer p,int d){CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new DocumentationOpenPacket(d));}public static void fireOmniTool(){CHANNEL.sendToServer(new OmniToolFirePacket());}public static void requestStarMapTravel(BlockPos p,int q,int s,int pl){CHANNEL.sendToServer(new StarMapTravelPacket(p,q,s,pl));}public static void requestStarMapFleetAttack(BlockPos p){CHANNEL.sendToServer(new StarMapFleetAttackPacket(p));}public static void requestStarMapEconomy(BlockPos p,int action){CHANNEL.sendToServer(new StarMapEconomyPacket(p,action));}public static void requestStarMapShipDispatch(BlockPos p,int shipType,int q,int s,int pl){CHANNEL.sendToServer(new StarMapShipDispatchPacket(p,shipType,q,s,pl));}public static void requestContractAbandon(int slot){CHANNEL.sendToServer(new ContractAbandonPacket(slot));}public static void syncAndroidState(ServerPlayer p){AndroidData.Ability a=AndroidData.getSelectedAbility(p);CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new AndroidStatePacket(AndroidData.isAndroid(p),AndroidData.getEnergy(p),AndroidData.getParts(p),a.ordinal(),AndroidData.getRemainingCooldown(p,a,p.level().getGameTime()),AndroidData.getActiveAbilityFlags(p),AndroidData.getExperience(p),AndroidData.getLevel(p),AndroidData.getSelectedPerks(p)));}}
